#include <iostream>
#include <string>
using namespace std;

int main() {
    string s;
    int x, y;

    cin >> s >> x;

    const string months[] = {
        "January", "February", "March", "April",
        "May", "June", "July", "August",
        "September", "October", "November", "December"
    };

    for (y = 0; y < 12; ++y) {
        if (months[y] == s) break;
    }

    cout << months[(y + x) % 12];
    return 0;
}

